SELECT (SELECT COUNT(*)=8 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='accesos_tributarios' AND column_name IN ('funcionario_id','login_hash','perfil','contribuyente_id','activo','asignado_por','revision','updated_at')) AND (SELECT COUNT(*)=1 FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND table_name='accesos_tributarios' AND referenced_table_name='contribuyentes');
